    (path.isFirst &&
      /---(?:\s|$)/.test(
        options.originalText.slice(locStart(document), locStart(document) + 4),
      )) ||
    /**
     * %DIRECTIVE
     * ---
     */
    document.head.children.length > 0 ||
    /**
     * # end comment
     * ---
